function Bartering.NamedPlaces.getLocations()
    return Bartering.NamedPlaces.Locations[Bartering.NamedPlaces.BUILD]
end

function Bartering.NamedPlaces.floorsForPoint(metaGrid, x, y)
    local building = metaGrid:getBuildingAt(x, y)
    if not building then
        return nil
    end
    local rooms = building:getRooms()
    local found = {}
    local hit
    for i = 0, rooms:size() - 1 do
        local room = rooms:get(i)
        if x >= room:getX() and x <= room:getX2() and y >= room:getY() and y <= room:getY2() then
            found[room:getZ()] = true
            hit = true
        end
    end
    if not hit then
        for i = 0, rooms:size() - 1 do
            found[rooms:get(i):getZ()] = true
        end
    end
    local zs = {}
    for z in pairs(found) do
        table.insert(zs, z)
    end
    table.sort(zs)
    return #zs > 0 and zs or nil
end

function Bartering.NamedPlaces.roomsAtPoint(metaGrid, x, y)
    local rooms = {}
    for level = 0, 2 do
        local room = metaGrid:getRoomAt(x, y, level)
        if room then
            table.insert(rooms, { level = level, name = room:getName() })
        end
    end
    return rooms
end

return Bartering.NamedPlaces
